values
  ('hyponatraemia', 'Hyponatraemia', '{"alacsony nátriumszint","nátriumhiány"}', 'Hyponatraemia', 'Elektrolit- és sav-bázis', '{"news2","avpu"}', '{"na","k","krea","egfr","tsh"}', '{}', '{"hyponatraemia","nátrium","elektrolit"}', '{"brief_what": "A vér nátriumszintjének csökkenése. A nátrium a sejten kívüli tér fő ozmotikus anyaga, ezért a csökkenése vizet mozgat a sejtekbe — az agysejtek duzzadása adja a tüneteket.", "brief_why": "A leggyakoribb elektrolitzavar, és a korrekció maga is veszélyes: a túl gyors rendezés maradandó idegrendszeri károsodást okoz. A kezelés sebességét nem a kiindulási érték határozza meg, hanem az, milyen gyorsan alakult ki.", "when": ["Rutinszerű laborvizsgálat — gyakran tünetmentesen derül ki", "Fejfájás, hányinger, aluszékonyság", "Zavartság, elesés, különösen idős betegnél", "Görcsroham, tudatzavar — súlyos forma", "Vízhajtó, antidepresszáns vagy epilepszia elleni szer indítása után"], "examine": ["A folyadékállapot megítélése: kiszáradt, normális vagy túltöltött — ez dönti el a kiváltó okot és a kezelést", "Bőrturgor, nyálkahártyák, nyaki vénák, ödéma", "Tudatállapot és a változás üteme", "A gyógyszerlista átnézése: tiazid típusú vízhajtó, antidepresszáns, epilepszia elleni szer, fájdalomcsillapító", "A kialakulás ütemének tisztázása: van-e korábbi nátriumérték"], "labs": "Szérumnátrium, kálium, vesefunkció, vércukor. A vizelet nátriumtartalma és ozmolalitása a kiváltó ok elkülönítéséhez. Pajzsmirigy- és mellékvesefunkció, ha az ok nem tisztázott. A korrekció alatt a nátrium ismételt mérése kötelező — ez a biztonság feltétele.", "ekg": "Nem jellemző eltérés; súlyos formában a monitorozás része.", "imaging": "Koponya-képalkotás tudatzavar esetén, más ok kizárására.", "scores": "Az AVPU és a NEWS2 a tudatállapot és az általános állapot követésére. Külön súlyossági pontozó nincs — a tünetek súlyossága és a kialakulás üteme dönt.", "red_flags": ["Görcsroham, kóma, súlyos tudatzavar — sürgős, célzott kezelés szükséges", "Hányás, erős fejfájás gyorsan csökkenő nátrium mellett", "Huszonnégy óránál rövidebb idő alatt kialakult csökkenés", "A korrekció során a nátrium túl gyors emelkedése — ez önmagában is veszélyhelyzet", "Súlyos kiszáradás vagy folyadéktúltöltés"], "apn_focus": ["A kialakulás ütemének tisztázása a legfontosabb kérdés: a korábbi laborérték felkutatása többet ér, mint a mostani érték pontossága", "A folyadékállapot megítélése a betegágy mellett — ez vezeti a kezelést, és ezt az ápoló látja legjobban", "A korrekció sebességének figyelése: a nátrium túl gyors emelkedése maradandó károsodást okoz, ezért a mérési rend betartása nem formaság", "A folyadékbevitel pontos mérése és dokumentálása", "A gyógyszerlista átnézése: a tiazid típusú vízhajtó és több gyakori szer is okozhatja", "Idős betegnél a zavartság és az elesés gyakran az egyetlen jel"], "treatment": ["A kiváltó ok kezelése — ez a legtöbb esetben elegendő", "A folyadékállapot szerint: kiszáradásnál pótlás, túltöltésnél megszorítás", "Súlyos tünetek esetén célzott, ellenőrzött kezelés intenzív felügyelet mellett", "A korrekció sebességének szigorú korlátozása — a napi emelkedés mértéke meghatározott, és a túllépés önmagában kezelendő szövődmény", "A kiváltó gyógyszer elhagyása vagy cseréje"], "followup": ["A nátrium ismételt ellenőrzése a korrekció alatt és után", "A kiváltó ok tisztázása, ha még nem történt meg", "A gyógyszeres kezelés felülvizsgálata", "Ismétlődés esetén részletes kivizsgálás"], "source_name": "Európai ajánlás a hyponatraemia kórisméjéről és kezeléséről", "source_url": "https://academic.oup.com/ndt", "version": "2023", "updated": "2026-09-15", "evidence": "A korrekció sebességének korlátozása erős ajánlás: a túl gyors rendezés okozta idegrendszeri károsodás jól dokumentált és megelőzhető."}'::jsonb, 'published', '1', false),
  ('hypernatraemia', 'Hypernatraemia', '{"magas nátriumszint"}', 'Hypernatraemia', 'Elektrolit- és sav-bázis', '{"avpu","news2"}', '{"na","krea","egfr","gluk"}', '{}', '{"hypernatraemia","nátrium","kiszáradás"}', '{"brief_what": "A vér nátriumszintjének emelkedése, ami szinte mindig vízhiányt jelent — nem nátriumtöbbletet. A sejtekből víz áramlik ki, és ez okozza a tüneteket.", "brief_why": "Kiszolgáltatott betegek betegsége: azoké, akik nem tudnak inni vagy jelezni a szomjúságukat. Az idős, tudatzavaros és szondával táplált betegnél a kialakulása gyakran az ellátás hiányosságát jelzi, ezért nagyrészt megelőzhető.", "when": ["Idős, tudatzavaros vagy szondával táplált beteg laborértéke", "Szomjúság, száraz nyálkahártyák", "Aluszékonyság, izomgyengeség, ingerlékenység", "Csökkent vizeletmennyiség", "Nagy vizeletmennyiség hígnak látszó vizelettel — vesebetegség lehetősége"], "examine": ["A folyadékállapot: nyálkahártyák, bőrturgor, vérnyomás, pulzus", "A folyadékbevitel tényleges mennyisége — nem a felajánlott, hanem az elfogyasztott", "A vizeletmennyiség és -jelleg", "Tudatállapot", "Az önálló ivás képessége: tud-e inni, jelzi-e a szomjúságot", "Láz, izzadás, hasmenés — fokozott vesztés"], "labs": "Szérumnátrium, vércukor, vesefunkció. A vizelet ozmolalitása és nátriumtartalma a vesebetegség elkülönítéséhez. A korrekció alatt a nátrium ismételt mérése kötelező.", "ekg": "Nem jellemző eltérés.", "imaging": "Nincs szerepe a szokásos esetben.", "scores": "Az AVPU a tudatállapot követésére. Külön pontozó nincs.", "red_flags": ["Tudatzavar, görcsroham", "Súlyos kiszáradás, vérnyomásesés", "Vizeletürítés hiánya", "Gyorsan emelkedő érték", "A korrekció során a nátrium túl gyors csökkenése — agyödéma kockázata"], "apn_focus": ["A megelőzés a legfontosabb: a rendszeres itatás és a folyadékbevitel tényleges mérése azoknál, akik nem tudnak maguktól inni", "A szondás táplálás melletti vízpótlás: a tápszer önmagában nem fedezi a vízszükségletet, és ennek elmulasztása gyakori ok", "A folyadéklap pontos vezetése — a becsült bevitel megtévesztő", "A korrekció sebességének figyelése: a túl gyors csökkentés agyödémát okoz", "A szomjúság jelzésének figyelése olyan betegnél, aki nem tud beszélni", "Láz, izzadás, hasmenés melletti fokozott igény felismerése"], "treatment": ["Vízpótlás, lehetőleg szájon át vagy szondán át — ez a legbiztonságosabb", "Vénás pótlás, ha a szájon át adott nem elegendő", "A korrekció sebességének korlátozása: a túl gyors csökkentés agyödémát okoz", "A kiváltó ok kezelése: láz, hasmenés, vesebetegség", "A szondás táplálás melletti vízmennyiség újraszámítása"], "followup": ["A nátrium ismételt ellenőrzése", "A folyadékbevitel rendjének rögzítése az ápolási tervben", "Ismétlődés esetén az ellátási rend felülvizsgálata"], "source_name": "Nemzetközi ajánlások a nátriumháztartás zavarairól", "source_url": "https://academic.oup.com/ndt", "version": "2023", "updated": "2026-09-15", "evidence": "A korrekció sebességének korlátozása itt is erős ajánlás. A megelőzés — rendszeres itatás és a szondás táplálás melletti vízpótlás — a leghatékonyabb beavatkozás."}'::jsonb, 'published', '1', false),
  ('hypokalaemia', 'Hypokalaemia', '{"alacsony káliumszint","káliumhiány"}', 'Hypokalaemia', 'Elektrolit- és sav-bázis', '{"news2"}', '{"k","mg","na","krea"}', '{"hypok"}', '{"hypokalaemia","kálium","elektrolit"}', '{"brief_what": "A vér káliumszintjének csökkenése. A kálium a szívizom és a vázizom ingerelhetőségét szabályozza, ezért a hiánya ritmuszavart és izomgyengeséget okoz.", "brief_why": "Gyakori, és a következménye lehet életveszélyes ritmuszavar — különösen digoxint szedő betegnél. A pótlás viszont önmagában gyakran sikertelen: ha a magnézium is alacsony, a kálium nem marad a sejtekben.", "when": ["Vízhajtó szedése — a leggyakoribb ok", "Hányás, hasmenés, hosszan tartó szondás leszívás", "Izomgyengeség, görcsök, fáradékonyság", "Ritmuszavar, szívdobogásérzés", "EKG-eltérés: lapos T-hullám, U-hullám megjelenése"], "examine": ["Izomerő vizsgálata: a gyengeség a végtagokon kezdődik", "Szívritmus és pulzus", "A vesztés forrásának keresése: vízhajtó, hányás, hasmenés", "A gyógyszerlista: vízhajtó, inzulin, béta-izgató, szteroid", "Digoxin szedése — ez emeli a legjobban a kockázatot"], "labs": "Szérumkálium és magnézium együtt — a magnézium önálló mérése itt nem elhagyható, mert az alacsony magnézium mellett a káliumpótlás hatástalan. Emellett nátrium, vesefunkció, sav-bázis állapot.", "ekg": "Lapos vagy fordított T-hullám, ST-depresszió, és a legjellemzőbb jel: az U-hullám megjelenése a T után. A kettő összeolvadhat, ami látszólagos QT-megnyúlást ad — de nem a QT nyúlt meg, hanem U-hullám jelent meg.", "imaging": "Nincs szerepe.", "scores": "Külön pontozó nincs. A NEWS2 az általános állapot követésére.", "red_flags": ["Ritmuszavar vagy EKG-eltérés — sürgős pótlás monitorozás mellett", "Digoxin szedése alacsony kálium mellett — életveszélyes kombináció", "Súlyos izomgyengeség, légzésizom-érintettség", "Együtt fennálló alacsony magnéziumszint — enélkül a pótlás hatástalan", "Vesztés folyamatos forrása, amit nem szüntettek meg"], "apn_focus": ["A magnézium együttes mérése és pótlása: alacsony magnézium mellett a káliumpótlás hatástalan — ez a leggyakoribb oka a „nem emelkedő\" káliumnak", "A vénás káliumpótlás sebessége szigorúan korlátozott: a túl gyors adás szívmegállást okozhat, ezért a beadási rend betartása nem formaság", "A vénás pótlás fájdalmas és irritálja a vénát — a hígítás és a beadási hely megválasztása számít", "Digoxint szedő betegnél a kálium ellenőrzése külön figyelmet érdemel", "A vesztés forrásának megszüntetése: a pótlás önmagában nem elég, ha a vízhajtó vagy a hasmenés folytatódik", "A szájon át adott pótlás étkezés közben kevesebb gyomorpanaszt okoz"], "treatment": ["Káliumpótlás szájon át, ha az állapot engedi — ez a biztonságosabb út", "Vénás pótlás súlyos hiánynál vagy ritmuszavar mellett, meghatározott sebességgel, monitorozás mellett", "Magnéziumpótlás, ha az is alacsony — enélkül a kálium nem rendeződik", "A kiváltó ok kezelése: vízhajtó felülvizsgálata, hányás csillapítása"], "followup": ["A kálium és a magnézium ismételt ellenőrzése", "A vízhajtó adagjának felülvizsgálata", "Kálium-megtakarító szer mérlegelése tartós vesztésnél"], "source_name": "Nemzetközi ajánlások az elektrolitzavarok kezeléséről", "source_url": "https://www.ncbi.nlm.nih.gov/books/NBK482465/", "version": "2024", "updated": "2026-09-15", "evidence": "A magnéziumpótlás szükségessége a káliumhiány rendezéséhez jól alátámasztott. A vénás pótlás sebességének korlátozása biztonsági követelmény."}'::jsonb, 'published', '1', false),
  ('hypocalcaemia', 'Hypocalcaemia', '{"alacsony kalciumszint","kalciumhiány"}', 'Hypocalcaemia', 'Elektrolit- és sav-bázis', '{}', '{"ca","mg","phos","vitd","krea"}', '{"hypoca"}', '{"hypocalcaemia","kalcium","elektrolit"}', '{"brief_what": "A vér kalciumszintjének csökkenése. A kalcium az idegek és az izmok ingerelhetőségét szabályozza, ezért a hiánya fokozott ingerlékenységet okoz — görcsös összehúzódásokat és zsibbadást.", "brief_why": "A mért összkalcium megtévesztő lehet: a fehérjéhez kötött rész nem aktív, ezért alacsony albuminszint mellett a valós, szabad kalcium normális lehet. A korrekció elmulasztása és a fölösleges kezelés egyaránt ebből ered.", "when": ["Szájkörüli és ujjbegyi zsibbadás", "Izomgörcsök, kézgörcs", "Pajzsmirigyműtét után — a mellékpajzsmirigy sérülése gyakori ok", "Vesebetegség, D-vitamin-hiány", "Nagy mennyiségű vérkészítmény adása után"], "examine": ["A jellegzetes izomingerlékenységi jelek vizsgálata: az arcideg megkopogtatása és a felkar leszorítása kiváltja a görcsös összehúzódást", "Zsibbadás elhelyezkedése: szájkörüli, ujjbegyi", "Görcskészség, izomrángás", "Műtéti heg a nyakon — a pajzsmirigyműtét utáni forma gyakori", "Légzés: súlyos formában gégegörcs alakulhat ki"], "labs": "Az összkalcium mellett az albumin is szükséges, mert az alacsony albumin hamisan alacsony összkalciumot ad. Ahol elérhető, az ionizált kalcium mérése pontosabb. Emellett magnézium, foszfát, D-vitamin, vesefunkció és mellékpajzsmirigy-hormon.", "ekg": "A leghosszabb QT-t adó elektrolitzavar: az ST-szakasz nyúlik meg, a T-hullám alakja viszont változatlan marad. Ez különíti el a gyógyszer okozta QT-megnyúlástól.", "imaging": "Nincs szerepe a szokásos esetben.", "scores": "Külön pontozó nincs.", "red_flags": ["Gégegörcs, légzési nehézség — életveszélyes", "Görcsroham", "Ritmuszavar vagy jelentős QT-megnyúlás", "Pajzsmirigyműtét után gyorsan csökkenő érték", "Együtt fennálló alacsony magnéziumszint"], "apn_focus": ["Az albumin ismerete a kalciumérték értelmezéséhez: alacsony albumin mellett az összkalcium hamisan alacsony, és fölösleges kezeléshez vezethet", "A jellegzetes vizsgálati jelek ismerete — ezekkel a betegágy mellett megerősíthető a gyanú", "Pajzsmirigyműtét után a kalcium rendszeres ellenőrzése és a zsibbadás jelzésének kérése", "A vénás kalciumpótlás lassú beadása: a gyors adás ritmuszavart okozhat, és a szer a szövetbe kerülve elhalást okoz", "Digoxint szedő betegnél a vénás kalciumpótlás fokozott óvatosságot igényel", "A magnézium együttes ellenőrzése"], "treatment": ["Tünetmentes, enyhe formában szájon át adott kalcium és D-vitamin", "Tünetekkel járó vagy súlyos formában vénás pótlás, lassan, monitorozás mellett", "Magnéziumpótlás, ha az is alacsony", "A kiváltó ok kezelése: D-vitamin-hiány, vesebetegség, mellékpajzsmirigy-zavar"], "followup": ["A kalcium és az albumin ismételt ellenőrzése", "Pajzsmirigyműtét után tartós követés", "D-vitamin-pótlás beállítása"], "source_name": "Nemzetközi endokrinológiai és nefrológiai ajánlások a kalciumháztartás zavarairól", "source_url": "https://www.ncbi.nlm.nih.gov/books/NBK430912/", "version": "2024", "updated": "2026-09-15", "evidence": "Az albuminra korrigált vagy ionizált kalcium használata a helyes megítélés feltétele. A vénás pótlás lassú beadása biztonsági követelmény."}'::jsonb, 'published', '1', false),
  ('hypercalcaemia', 'Hypercalcaemia', '{"magas kalciumszint"}', 'Hypercalcaemia', 'Elektrolit- és sav-bázis', '{"avpu"}', '{"ca","phos","krea","egfr"}', '{"hyperca"}', '{"hypercalcaemia","kalcium","daganat"}', '{"brief_what": "A vér kalciumszintjének emelkedése. A két leggyakoribb ok a mellékpajzsmirigy túlműködése és a daganatos betegség — a kettő aránya a súlyosságtól függ.", "brief_why": "A tünetek jellegtelenek, és gyakran más okra vezetik vissza őket: a zavartság, a székrekedés és a fáradtság idős betegnél sok mindenből eredhet. A magas érték viszont daganatot jelezhet, ezért a kivizsgálás elmulasztása súlyos következménnyel jár.", "when": ["Rutinszerű laborvizsgálat — gyakran így derül ki", "Fáradtság, gyengeség, hangulatváltozás", "Fokozott szomjúság és vizeletürítés", "Székrekedés, hányinger", "Zavartság, aluszékonyság — súlyos formában", "Csontfájdalom, vesekő"], "examine": ["Folyadékállapot: a magas kalcium fokozott vizeletürítést okoz, ami kiszáradáshoz vezet", "Tudatállapot", "Daganatra utaló jelek: fogyás, csontfájdalom, nyirokcsomók", "A gyógyszerlista: kalcium- és D-vitamin-készítmények, tiazid típusú vízhajtó, lítium", "Székletürítés"], "labs": "Az összkalcium mellett albumin, vagy ionizált kalcium. Foszfát, vesefunkció, mellékpajzsmirigy-hormon — ez utóbbi különíti el a két fő okot. Daganat gyanújánál célzott vizsgálatok.", "ekg": "Rövid QT: az ST-szakasz megrövidül vagy eltűnik, és a T-hullám szinte közvetlenül a QRS után következik. Súlyos formában ritmuszavar.", "imaging": "Daganatkeresés, ha a mellékpajzsmirigy-hormon nem emelkedett. Csontérintettség vizsgálata.", "scores": "Az AVPU a tudatállapot követésére.", "red_flags": ["Tudatzavar, kóma", "Ritmuszavar", "Súlyos kiszáradás", "Gyorsan emelkedő érték daganatos betegnél — sürgősségi állapot", "Vesefunkció-romlás"], "apn_focus": ["A tünetek felismerése: a zavartság, a székrekedés és a fáradtság együttese idős betegnél gyakran nem kerül összefüggésbe a kalciummal", "A folyadékpótlás a kezelés a