-- A hyperkalaemia a nefrológiai blokkban készült el, de szakmailag ide
-- tartozik a többi ionzavar mellé. Átsoroljuk, hogy egy helyen legyenek.
update public.diseases set specialty = 'Elektrolit- és sav-bázis'
where slug = 'hyperkalaemia';

-- ══ Ellenőrzés ═══════════════════════════════════════════
-- A kilenc új és az átsorolt hyperkalaemia után nem maradhat csonk.
select slug, name,
  case when body ->> 'brief_what' is null then 'csonk' else 'kidolgozott' end as allapot
from public.diseases
where specialty = 'Elektrolit- és sav-bázis' and status = 'published'
order by allapot, name;
